import{d as c,C as t,o as u,c as b,j as a,a as o,E as n,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第八章","description":"由水的利物、处下与不争，理解七善怎样落实到处事。","frontmatter":{"title":"道德经第八章","description":"由水的利物、处下与不争，理解七善怎样落实到处事。","category":"guide","aliases":["道德经第八章","老子第八章","dao de jing chapter 8"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-08.md","filePath":"daoism/dao-de-jing/chapter-08.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-08.md"},y=c({...p,setup(g){const i=[{id:"water-benefits-without-contending",label:"上善若水",showLabel:!0,sentences:[["上善若水。"],["水善利万物而",{text:"不争",glossary:"buzheng"},"，处众人之所",{text:"恶",glossary:"wu"},"，故",{text:"几",glossary:"ji"},"于道。"]],note:["【白话】最好的善如同水。水善于使万物得到益处，却不与它们争；它停留在人们不愿处的低下之地，所以接近于道。","【王弼注择要】「人恶卑也。」「道无水有，故曰几也。」王弼先以人不愿处卑说明水的处下，再区分无形之道与有形之水，所以只说几于道。","【读法】恶读 wù，指厌恶；几读 jī，指接近。水是用来引路的比喻，有形之水并不就等于道，也不是水的一切物理表现都成了处事规范。"]},{id:"seven-ways-of-being-good",label:"居善地，心善渊",showLabel:!0,sentences:[["居善地，心善",{text:"渊",glossary:"yuan"},"，",{text:"与",glossary:"yu"},"善",{text:"仁",glossary:"ren"},"，言善信，"],["政善治，事善能，动善时。"]],note:["【白话】居处善于择取合宜之地，心境善于保持深静，与人相交善于仁厚，言语善于守信，治理善于使秩序安定，办事善于发挥能力，行动善于把握时机。","【王弼注择要】王弼在章末概括说「言人皆应于治道也」。水的譬喻由此落到人的居处、心志、交往、言行与治理，不停在一个柔顺的形象上。","【读法】七个善分别落在不同事情上，能力、信用、时机都不能省略。与在此按交与、相与解；善仁也有从施与解读的路向，不必把这里的译法当成唯一断定。"]},{id:"no-contention-no-blame",label:"夫唯不争，故无尤",showLabel:!0,sentences:[["夫唯不争，故无",{text:"尤",glossary:"you"},"。"]],note:["【白话】正因为不以争夺的方式处事，所以没有由此招致的过咎。","【读法】不争承接利物、处下与七善，不是只在口头上退让；无尤说的是本章所赞许的处事状态，也不保证一个人从此不遇责难、误解或损害。"]}],r=[{id:"buzheng",term:"不争",sense:1},{id:"wu",term:"恶",sense:1,pinyin:"wù",context:"「处众人之所恶」指人所厌恶的低下之处，与第二章读 è 的丑义区分。"},{id:"ji",term:"几",sense:1,pinyin:"jī"},{id:"yuan",term:"渊",sense:1},{id:"yu",term:"与",sense:1},{id:"ren",term:"仁",sense:1},{id:"you",term:"尤",sense:1}];return(x,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第八章",tabindex:"-1"},[o("道德经第八章 "),a("a",{class:"header-anchor",href:"#道德经第八章","aria-label":'Permalink to "道德经第八章"'},"​")],-1)),n(s,{title:"水如何利物，人如何处事",summary:"读「上善若水」，既看水的利物与处下，也要读完居、心、与、言、政、事、动七项。全章的不争有实际的能力与信用作支撑，不只是一种温柔姿态。",points:[{label:"先读",text:"利物、不争、处下为何一起出现？"},{label:"再辨",text:"七个善分别要求怎样的实际表现？"},{label:"后想",text:"水为什么只是几于道？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),n(l,{sections:i,glossary:r,tone:"ink",density:"comfortable","aria-label":"《道德经》第八章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"水善利万物而不争，处众人之所恶。",tone:"取象",guide:"水对万物有实际益处，又不以居高争先显示价值。两面并读，才不会把不争误成没有作为。"},{text:"故几于道。",tone:"留界",guide:"几是接近。王弼区分道无与水有，为比喻留出界限，不把有形之物直接等同于根源。"},{text:"政善治，事善能，动善时。",tone:"落实",guide:"本章并未回避治理、能力与时机。善须在具体事情上合宜，不是只以退让的姿态取得一个好名声。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-水的哪些特点被本章取来作比" tabindex="-1">象：水的哪些特点被本章取来作比？ <a class="header-anchor" href="#象-水的哪些特点被本章取来作比" aria-label="Permalink to &quot;象：水的哪些特点被本章取来作比？&quot;">​</a></h3><p>利物说明有益，处下说明不争取众人看重的高处，不争则把二者连成处事方式。本章选取这些特点，是为了展开对善的理解；若把洪水等一切水象都纳入同一劝诫，就超出了这段比喻的具体用法。</p><h3 id="理-既然不争-为什么还要「事善能」" tabindex="-1">理：既然不争，为什么还要「事善能」？ <a class="header-anchor" href="#理-既然不争-为什么还要「事善能」" aria-label="Permalink to &quot;理：既然不争，为什么还要「事善能」？&quot;">​</a></h3><p>不争针对争夺地位、独占利益的方式，不取消把事情做好的能力。七善之中有信、治、能、时，说明合宜的行动需要可信、有效且适时。只说自己不争，却不履行承诺、也不解决问题，不能概括这一章的善。</p><h3 id="用-怎样理解处下而不压低自己" tabindex="-1">用：怎样理解处下而不压低自己？ <a class="header-anchor" href="#用-怎样理解处下而不压低自己" aria-label="Permalink to &quot;用：怎样理解处下而不压低自己？&quot;">​</a></h3><p>愿意承担不显眼却必要的工作，可以是处下的现代联想；但工作价值、相应资源和个人边界仍应说清。不能要求某些人永远留在低位，也不能以不争劝人放弃应有的权益。处下是行动者的自觉，不是别人强加的身份。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>让善意有具体的做法。</strong> 希望帮助别人时，可以逐项检查：地点合适吗，是否听清需要，承诺可信，能力足够，时机合宜？七善提供的是细分处事的线索，不必缩成一句好心即可。</p><p><strong>把不显眼的工作做得可见。</strong> 文档维护、倾听与协调常不如台前表达受关注，却可能支持整体运行。愿意做这些事时，也可以记录投入与成果，让合作不依赖少数人默默承担。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：在七善之中，我目前最需要补的是信用、能力，还是时机判断？一件低调的工作，怎样既利于事情，又不使承担者被忽略？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>「政善治」保留本站通行文字，HFL 电子录文作「正善治」；「几」取接近义，读 jī。</li><li>「与善仁」本页取交与仁厚之义，另有侧重施与的解释；不据此预设后文各章关于仁的评价。</li><li>「无尤」不改译成不受任何责难，也不把不争扩成不能申明权益。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，005b</a>。</p>',15))])}}});export{_ as __pageData,y as default};
